import express from "express";
import cors from "cors";
import pinoHttp from "pino-http";
import { logger } from "./config/logger";
import { successResponse } from "./utils/api-response";
import authRouter from "./modules/auth/auth.routes";
import adminRouter from "./modules/admin/admin.routes";
import usersRouter from "./modules/users/users.routes";
import customerRouter from "./modules/customer/customer.routes";
import driverRouter from "./modules/driver/driver.routes";
import vehicleTypeRouter from "./modules/vehicle-type/vehicle-type.routes";
import paymentRouter from "./modules/payment/payment.routes";
import withdrawRouter from "./modules/withdraw/withdraw.routes";
import invoiceRouter from "./modules/invoice/invoice.routes";
import { adminSupportRouter, supportRouter } from "./modules/support/ticket.routes";
import { adminRatingRouter, ratingRouter } from "./modules/rating/rating.routes";
import operationalZoneRouter from "./modules/operational-zone/operational-zone.routes";
import notificationRouter from "./modules/notification/notification.routes";
import {
  driverDocumentsAdminRouter,
  driverDocumentsDriverRouter,
} from "./modules/driver-documents/driver-document.routes";
import driverProfileRouter from "./modules/driver-profile/driver-profile.routes";
import { globalErrorHandler, notFoundHandler } from "./middlewares/error.middleware";


export const app = express();

app.use(cors());
app.use(express.json());
app.use(pinoHttp({ logger }));

app.get("/api/v1/health", (_req, res) => {
  return res.status(200).json(successResponse("Service healthy"));
});

app.use("/api/v1/auth", authRouter);
app.use("/api/v1/admin", adminRouter);
app.use("/api/admin", adminRouter);
app.use("/api/v1/users", usersRouter);
app.use("/api/users", usersRouter);
app.use(customerRouter);
app.use(driverRouter);
app.use(driverDocumentsDriverRouter);
app.use("/api/v1/driver", driverProfileRouter);
app.use("/api/v1/admin", driverDocumentsAdminRouter);
app.use("/api/admin", driverDocumentsAdminRouter);
app.use(operationalZoneRouter);
app.use("/api/vehicle-types", vehicleTypeRouter);
app.use(notificationRouter);
app.use(paymentRouter);
app.use(withdrawRouter);
app.use(invoiceRouter);
app.use("/api/support", supportRouter);
app.use("/api/admin", adminSupportRouter);
app.use(ratingRouter);
app.use(adminRatingRouter);

app.use(notFoundHandler);
app.use(globalErrorHandler);

export default app;

import pino from "pino";
import { env } from "./env";

export const logger = pino({
  level: env.NODE_ENV === "development" ? "debug" : "info",
});

import dotenv from "dotenv";
import { z } from "zod";

dotenv.config({ path: ".env.local" });

const booleanFromEnv = z.preprocess((value) => {
  if (typeof value === "boolean") {
    return value;
  }

  if (typeof value === "string") {
    const normalized = value.trim().toLowerCase();
    if (["true", "1", "yes", "y", "on"].includes(normalized)) {
      return true;
    }
    if (["false", "0", "no", "n", "off"].includes(normalized)) {
      return false;
    }
  }

  return value;
}, z.boolean());

const envSchema = z.object({
  NODE_ENV: z.enum(["development", "production", "test"]).default("development"),
  PORT: z.coerce.number().default(3000),
  MONGO_URI: z.string().min(1),
  JWT_ACCESS_SECRET: z.string().min(16),
  JWT_REFRESH_SECRET: z.string().min(16),
  JWT_ACCESS_EXPIRES_IN: z.string().default("15m"),
  JWT_REFRESH_EXPIRES_IN: z.string().default("7d"),
  BCRYPT_SALT_ROUNDS: z.coerce.number().min(8).max(15).default(10),
  SMTP_HOST: z.string().min(1),
  SMTP_PORT: z.coerce.number().min(1),
  SMTP_USER: z.string().min(1),
  SMTP_PASSWORD: z.string().min(1),
  SMTP_FROM_EMAIL: z.string().min(1),
  SMTP_TLS_REJECT_UNAUTHORIZED: booleanFromEnv.default(true),
  OSRM_URL: z.string().min(1),
  RAZORPAY_KEY_ID: z.string().min(1),
  RAZORPAY_KEY_SECRET: z.string().min(1),
  AWS_ACCESS_KEY_ID: z.string().optional(),
  AWS_SECRET_ACCESS_KEY: z.string().optional(),
  AWS_REGION: z.string().optional(),
  /** Default S3 bucket; also fallback when AWS_S3_BUCKET_DOCUMENTS is unset. */
  AWS_S3_BUCKET: z.string().optional(),
  /** Dedicated bucket for driver/taxi document uploads (recommended). Overrides AWS_S3_BUCKET for file storage when set. */
  AWS_S3_BUCKET_DOCUMENTS: z.string().optional(),
});

const parsedEnv = envSchema.safeParse(process.env);

if (!parsedEnv.success) {
  throw new Error(`Invalid environment configuration: ${parsedEnv.error.message}`);
}

export const env = parsedEnv.data;
const isTest = process.env.NODE_ENV === "test";

export const MONGO_URI = isTest
  ? "mongodb://127.0.0.1:27017/taxi_app"
  : env.MONGO_URI;

export type ApiResponse<T> = {
  success: boolean;
  message: string;
  data?: T;
  error?: unknown;
};

export const successResponse = <T>(message: string, data?: T): ApiResponse<T> => ({
  success: true,
  message,
  data,
});

export const errorResponse = (message: string, error?: unknown): ApiResponse<never> => ({
  success: false,
  message,
  error,
});

import { Router } from "express";
import { loginController, refreshController } from "./auth.controller";
import { validate } from "../../middlewares/validate.middleware";
import { loginSchema, refreshSchema } from "./auth.validation";

const authRouter = Router();

authRouter.post("/login", validate(loginSchema), loginController);
authRouter.post("/refresh", validate(refreshSchema), refreshController);

export default authRouter;

import { NextFunction, Request, Response } from "express";
import { successResponse } from "../../utils/api-response";
import { loginUser, refreshAccessToken } from "./auth.service";

export const loginController = async (req: Request, res: Response, next: NextFunction) => {
  try {
    const { email, password } = req.body;
    const data = await loginUser(email, password);
    return res.status(200).json(successResponse("Login successful", data));
  } catch (error) {
    return next(error);
  }
};

export const refreshController = async (req: Request, res: Response, next: NextFunction) => {
  try {
    const { refreshToken } = req.body;
    const data = await refreshAccessToken(refreshToken);
    return res.status(200).json(successResponse("Token refreshed", data));
  } catch (error) {
    return next(error);
  }
};

import { HttpError } from "../../utils/http-error";
import { comparePassword } from "../../utils/password.util";
import { generateAccessToken, generateRefreshToken, verifyRefreshToken } from "../../utils/jwt.util";
import { findUserByEmail, findUserById } from "../users/users.repository";

export const loginUser = async (email: string, password: string) => {
  const user = await findUserByEmail(email);

  if (!user || !user.is_active) {
    throw new HttpError(401, "Invalid credentials");
  }

  const isPasswordValid = await comparePassword(password, user.password_hash);
  if (!isPasswordValid) {
    throw new HttpError(401, "Invalid credentials");
  }

  const accessToken = generateAccessToken(user.id, user.role);
  const refreshToken = generateRefreshToken(user.id, user.role);

  return {
    accessToken,
    refreshToken,
    user: {
      id: user.id,
      name: user.name,
      email: user.email,
      role: user.role,
      is_blocked: user.is_blocked,
      blocked_reason: user.blocked_reason ?? null,
    },
  };
};

export const refreshAccessToken = async (refreshToken: string) => {
  const payload = verifyRefreshToken(refreshToken);

  if (payload.type !== "refresh") {
    throw new HttpError(401, "Invalid refresh token");
  }

  const user = await findUserById(payload.sub);
  if (!user || !user.is_active) {
    throw new HttpError(401, "Invalid refresh token");
  }

  return {
    accessToken: generateAccessToken(user.id, user.role),
  };
};

export class HttpError extends Error {
  statusCode: number;

  constructor(statusCode: number, message: string) {
    super(message);
    this.statusCode = statusCode;
  }
}

import bcrypt from "bcrypt";
import { env } from "../config/env";

export const hashPassword = async (plainPassword: string): Promise<string> => {
  return bcrypt.hash(plainPassword, env.BCRYPT_SALT_ROUNDS);
};

export const comparePassword = async (
  plainPassword: string,
  hashedPassword: string
): Promise<boolean> => {
  return bcrypt.compare(plainPassword, hashedPassword);
};

import jwt, { Secret, SignOptions } from "jsonwebtoken";
import { env } from "../config/env";
import { UserRole } from "../modules/users/users.types";

type TokenType = "access" | "refresh";

type TokenPayload = {
  sub: string;
  role: UserRole;
  type: TokenType;
};

export const generateAccessToken = (userId: string, role: UserRole): string => {
  const payload: TokenPayload = { sub: userId, role, type: "access" };
  const options: SignOptions = {
    expiresIn: env.JWT_ACCESS_EXPIRES_IN as SignOptions["expiresIn"],
  };
  return jwt.sign(payload, env.JWT_ACCESS_SECRET as Secret, options);
};

export const generateRefreshToken = (userId: string, role: UserRole): string => {
  const payload: TokenPayload = { sub: userId, role, type: "refresh" };
  const options: SignOptions = {
    expiresIn: env.JWT_REFRESH_EXPIRES_IN as SignOptions["expiresIn"],
  };
  return jwt.sign(payload, env.JWT_REFRESH_SECRET as Secret, options);
};

export const verifyAccessToken = (token: string): TokenPayload => {
  return jwt.verify(token, env.JWT_ACCESS_SECRET) as TokenPayload;
};

export const verifyRefreshToken = (token: string): TokenPayload => {
  return jwt.verify(token, env.JWT_REFRESH_SECRET) as TokenPayload;
};

import { UserModel, UserDocument } from "./users.model";
import { UserEntity } from "./users.types";

export const findUserByEmail = async (email: string): Promise<UserDocument | null> => {
  return UserModel.findOne({ email: email.toLowerCase().trim() });
};

export const findUserById = async (id: string): Promise<UserDocument | null> => {
  return UserModel.findById(id);
};

export const createUser = async (payload: UserEntity): Promise<UserDocument> => {
  return UserModel.create(payload);
};

import { Schema, model, HydratedDocument } from "mongoose";
import { DRIVER_STATUSES, DRIVER_VERIFICATION_STATUSES, USER_ROLES, UserEntity } from "./users.types";

export type UserDocument = HydratedDocument<UserEntity>;

const userSchema = new Schema<UserEntity>(
  {
    name: { type: String, required: true, trim: true },
    email: { type: String, required: true, lowercase: true, trim: true },
    phone: { type: String, required: false, trim: true },
    fcm_token: { type: String, required: false, trim: true },
    password_hash: { type: String, required: true },
    role: {
      type: String,
      enum: USER_ROLES,
      default: "CUSTOMER",
    },
    driver_status: {
      type: String,
      enum: DRIVER_STATUSES,
      default: undefined,
    },
    is_driver_verified: { type: Boolean, default: false },
    driver_verification_status: {
      type: String,
      enum: DRIVER_VERIFICATION_STATUSES,
      default: "PENDING",
    },
    driver_profile: { type: Schema.Types.Mixed, default: undefined },
    is_active: { type: Boolean, default: true },
    is_blocked: { type: Boolean, default: false },
    blocked_reason: { type: String, default: null, trim: true },
  },
  {
    collection: "users",
    timestamps: { createdAt: "created_at", updatedAt: "updated_at" },
  }
);

userSchema.index({ email: 1 }, { unique: true });
userSchema.index({ role: 1 });

export const UserModel = model<UserEntity>("User", userSchema);

export const USER_ROLES = ["ADMIN", "CUSTOMER", "DRIVER"] as const;
export type UserRole = (typeof USER_ROLES)[number];
export const DRIVER_STATUSES = ["ONLINE", "OFFLINE", "BUSY"] as const;
export type DriverStatus = (typeof DRIVER_STATUSES)[number];

export const DRIVER_VERIFICATION_STATUSES = ["PENDING", "APPROVED", "REJECTED"] as const;
export type DriverVerificationStatus = (typeof DRIVER_VERIFICATION_STATUSES)[number];

export type DriverProfileSnapshot = {
  dob?: Date | null;
  phone?: string | null;
  address?: string | null;
  emergency_contact?: string | null;
  license_number?: string | null;
  vehicle_reg_number?: string | null;
  vehicle_type_id?: string | null;
  vehicle_model?: string | null;
  vehicle_color?: string | null;
  pan_number?: string | null;
  aadhaar_number?: string | null;
  voter_id?: string | null;
  account_holder_name?: string | null;
  bank_name?: string | null;
  branch_name?: string | null;
  account_number?: string | null;
  ifsc_code?: string | null;
  account_type?: string | null;
  upi_id?: string | null;
  profile_completed?: boolean;
  updatedAt?: Date | null;
};

export type UserEntity = {
  name: string;
  email: string;
  phone?: string;
  fcm_token?: string;
  password_hash: string;
  role: UserRole;
  driver_status?: DriverStatus;
  /** Set for drivers only; ignored for other roles */
  is_driver_verified?: boolean;
  /** Set for drivers only; ignored for other roles */
  driver_verification_status?: DriverVerificationStatus;
  /** Driver profile snapshot mirrored for easy role=DRIVER lookups */
  driver_profile?: DriverProfileSnapshot;
  is_active: boolean;
  is_blocked: boolean;
  blocked_reason?: string;
};

import { Request, Response, NextFunction } from "express";
import { AnyZodObject } from "zod";
import { HttpError } from "../utils/http-error";

export const validate =
  (schema: AnyZodObject) => (req: Request, _res: Response, next: NextFunction) => {
    const validation = schema.safeParse({
      // GET (and some other) requests have no JSON body; Zod z.object({}) rejects undefined.
      body: req.body ?? {},
      params: req.params,
      query: req.query ?? {},
    });

    if (!validation.success) {
      return next(
        new HttpError(400, validation.error.issues[0]?.message || "Validation failed")
      );
    }

    return next();
  };

import { z } from "zod";

export const loginSchema = z.object({
  body: z.object({
    email: z.string().email(),
    password: z.string().min(6),
  }),
  params: z.object({}),
  query: z.object({}),
});

export const refreshSchema = z.object({
  body: z.object({
    refreshToken: z.string().min(1),
  }),
  params: z.object({}),
  query: z.object({}),
});

import { Router } from "express";
import { adminTestController, getActiveDriversController } from "./admin.controller";
import { requireAuth } from "../../middlewares/auth.middleware";
import { requireRole } from "../../middlewares/role.middleware";
import adminCustomerRouter from "./customer/admin-customer.routes";
import financeRouter from "../finance/finance.routes";

const adminRouter = Router();

adminRouter.use(requireAuth, requireRole(["ADMIN"]));
adminRouter.get("/test", adminTestController);
adminRouter.get("/drivers/active", getActiveDriversController);
adminRouter.use("/customers", adminCustomerRouter);
adminRouter.use("/", financeRouter);

export default adminRouter;

import { NextFunction, Request, Response } from "express";
import { successResponse } from "../../utils/api-response";
import { UserModel } from "../users/users.model";

export const adminTestController = (req: Request, res: Response) => {
  return res.status(200).json(
    successResponse("Admin route is accessible", {
      userId: req.authUser?.userId,
      role: req.authUser?.role,
      message: "Admin module base setup is working",
    })
  );
};

export const getActiveDriversController = async (
  _req: Request,
  res: Response,
  next: NextFunction
) => {
  try {
    const drivers = await UserModel.find({
      role: "DRIVER",
      is_active: true,
      is_blocked: false,
      driver_status: { $in: ["ONLINE", "BUSY"] },
    })
      .select("name email phone driver_status is_active is_blocked blocked_reason created_at")
      .sort({ updated_at: -1, created_at: -1 })
      .lean();

    return res.status(200).json(
      successResponse("Active drivers fetched successfully", {
        total: drivers.length,
        drivers: drivers.map((driver) => ({
          id: String(driver._id),
          name: driver.name,
          email: driver.email,
          phone: driver.phone ?? null,
          status: driver.driver_status ?? "OFFLINE",
          is_active: driver.is_active,
          is_blocked: driver.is_blocked,
          blocked_reason: driver.blocked_reason ?? null,
          joined_at: (driver as { created_at?: Date }).created_at ?? null,
        })),
      })
    );
  } catch (error) {
    return next(error);
  }
};

/** Drivers who completed admin verification (KYC approved). */
export const getVerifiedDriversController = async (
  _req: Request,
  res: Response,
  next: NextFunction
) => {
  try {
    const drivers = await UserModel.find({
      role: "DRIVER",
      is_driver_verified: true,
      driver_verification_status: "APPROVED",
    })
      .select(
        "name email phone driver_status is_driver_verified driver_verification_status created_at"
      )
      .sort({ updated_at: -1, created_at: -1 })
      .lean();

    return res.status(200).json(
      successResponse("Verified drivers fetched successfully", {
        total: drivers.length,
        drivers: drivers.map((driver) => ({
          id: String(driver._id),
          name: driver.name,
          email: driver.email,
          phone: driver.phone ?? null,
          driver_status: driver.driver_status ?? "OFFLINE",
          is_driver_verified: driver.is_driver_verified === true,
          driver_verification_status: driver.driver_verification_status ?? "PENDING",
          joined_at: (driver as { created_at?: Date }).created_at ?? null,
        })),
      })
    );
  } catch (error) {
    return next(error);
  }
};

import { NextFunction, Request, Response } from "express";
import jwt from "jsonwebtoken";
import { verifyAccessToken } from "../utils/jwt.util";
import { HttpError } from "../utils/http-error";

export const requireAuth = (req: Request, _res: Response, next: NextFunction) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return next(new HttpError(401, "Unauthorized"));
  }

  const raw = authHeader.slice(7).trim();
  if (!raw || raw === "undefined" || raw === "null") {
    return next(new HttpError(401, "Missing access token (check REST Client: run Admin login first, then use @adminAccessToken)"));
  }

  try {
    const payload = verifyAccessToken(raw);

    if (payload.type !== "access") {
      return next(new HttpError(401, "Invalid access token"));
    }

    req.authUser = { userId: payload.sub, role: payload.role };
    return next();
  } catch (error) {
    if (error instanceof jwt.TokenExpiredError) {
      return next(new HttpError(401, "Access token expired — log in again"));
    }
    if (error instanceof jwt.JsonWebTokenError) {
      return next(new HttpError(401, "Invalid access token — copy data.accessToken from login, or re-run Admin login"));
    }
    return next(new HttpError(401, "Invalid or expired token"));
  }
};

import { NextFunction, Request, Response } from "express";
import { UserRole } from "../modules/users/users.types";
import { HttpError } from "../utils/http-error";

export const requireRole = (allowedRoles: UserRole[]) => {
  return (req: Request, _res: Response, next: NextFunction) => {
    if (!req.authUser) {
      return next(new HttpError(401, "Unauthorized"));
    }

    if (!allowedRoles.includes(req.authUser.role)) {
      return next(new HttpError(403, "Forbidden"));
    }

    return next();
  };
};

import { Router } from "express";
import {
  getAdminCustomerDetailsController,
  getAdminCustomerRideHistoryController,
  getAdminCustomersController,
  updateAdminCustomerBlockStatusController,
} from "./admin-customer.controller";

const adminCustomerRouter = Router();

adminCustomerRouter.get("/", getAdminCustomersController);
adminCustomerRouter.get("/:id", getAdminCustomerDetailsController);
adminCustomerRouter.patch("/:id/block", updateAdminCustomerBlockStatusController);
adminCustomerRouter.get("/:id/rides", getAdminCustomerRideHistoryController);

export default adminCustomerRouter;

import { NextFunction, Request, Response } from "express";
import {
  getAdminCustomerDetails,
  getAdminCustomerRideHistory,
  getAdminCustomers,
  updateAdminCustomerBlockStatus,
} from "./admin-customer.service";

export const getAdminCustomersController = async (
  req: Request,
  res: Response,
  next: NextFunction
) => {
  try {
    const { page, limit, search } = req.query;
    const data = await getAdminCustomers(page, limit, search);
    return res.status(200).json(data);
  } catch (error) {
    return next(error);
  }
};

export const getAdminCustomerDetailsController = async (
  req: Request,
  res: Response,
  next: NextFunction
) => {
  try {
    const customerId = Array.isArray(req.params.id) ? req.params.id[0] : req.params.id;
    const data = await getAdminCustomerDetails(customerId);
    return res.status(200).json(data);
  } catch (error) {
    return next(error);
  }
};

export const updateAdminCustomerBlockStatusController = async (
  req: Request,
  res: Response,
  next: NextFunction
) => {
  try {
    const customerId = Array.isArray(req.params.id) ? req.params.id[0] : req.params.id;
    const { is_blocked, reason } = req.body;
    const data = await updateAdminCustomerBlockStatus(customerId, is_blocked, reason);
    return res.status(200).json(data);
  } catch (error) {
    return next(error);
  }
};

export const getAdminCustomerRideHistoryController = async (
  req: Request,
  res: Response,
  next: NextFunction
) => {
  try {
    const customerId = Array.isArray(req.params.id) ? req.params.id[0] : req.params.id;
    const data = await getAdminCustomerRideHistory(customerId);
    return res.status(200).json(data);
  } catch (error) {
    return next(error);
  }
};

import { isValidObjectId } from "mongoose";
import { HttpError } from "../../../utils/http-error";
import { RideModel } from "../../customer/ride/ride.model";
import { RatingModel } from "../../rating/rating.model";
import { UserModel } from "../../users/users.model";

const toPositiveInt = (value: unknown, fallback: number) => {
  const num = Number(value);
  if (!Number.isFinite(num) || num < 1) {
    return fallback;
  }
  return Math.floor(num);
};

const ensureCustomerId = (customerId: string) => {
  if (!isValidObjectId(customerId)) {
    throw new HttpError(400, "Invalid customer id");
  }
};

const getCustomerOrThrow = async (customerId: string) => {
  ensureCustomerId(customerId);

  const customer = await UserModel.findOne({ _id: customerId, role: "CUSTOMER" });
  if (!customer) {
    throw new HttpError(404, "Customer not found");
  }

  return customer;
};

export const getAdminCustomers = async (pageInput?: unknown, limitInput?: unknown, searchInput?: unknown) => {
  const page = toPositiveInt(pageInput, 1);
  const limit = Math.min(toPositiveInt(limitInput, 10), 100);
  const search = typeof searchInput === "string" ? searchInput.trim() : "";

  const query: Record<string, unknown> = { role: "CUSTOMER" };
  if (search) {
    query.$or = [{ email: { $regex: search, $options: "i" } }, { name: { $regex: search, $options: "i" } }];
  }

  const [customers, total] = await Promise.all([
    UserModel.find(query)
      .sort({ created_at: -1 })
      .skip((page - 1) * limit)
      .limit(limit),
    UserModel.countDocuments(query),
  ]);

  return {
    page,
    limit,
    total,
    total_pages: Math.ceil(total / limit) || 1,
    customers: customers.map((customer) => ({
      id: customer.id,
      name: customer.name,
      email: customer.email,
      phone: customer.phone ?? null,
      is_blocked: customer.is_blocked,
      blocked_reason: customer.blocked_reason ?? null,
      createdAt: customer.get("created_at"),
    })),
  };
};

export const getAdminCustomerDetails = async (customerId: string) => {
  const customer = await getCustomerOrThrow(customerId);
  const [totalTrips, completedTrips, cancelledTrips, ratingSummary] = await Promise.all([
    RideModel.countDocuments({ customer_id: customer.id }),
    RideModel.countDocuments({ customer_id: customer.id, status: "COMPLETED" }),
    RideModel.countDocuments({ customer_id: customer.id, status: "CANCELLED" }),
    RatingModel.aggregate<{ average_rating: number }>([
      { $match: { to_user_id: customer._id } },
      { $group: { _id: null, average_rating: { $avg: "$rating" } } },
      { $project: { _id: 0, average_rating: { $round: ["$average_rating", 1] } } },
    ]),
  ]);

  const rating = ratingSummary[0]?.average_rating ?? 0;

  return {
    id: customer.id,
    name: customer.name,
    email: customer.email,
    phone: customer.phone ?? null,
    is_active: customer.is_active,
    is_blocked: customer.is_blocked,
    blocked_reason: customer.blocked_reason ?? null,
    createdAt: customer.get("created_at"),
    updatedAt: customer.get("updated_at"),
    stats: {
      total_trips: totalTrips,
      completed_trips: completedTrips,
      cancelled_trips: cancelledTrips,
      rating,
    },
  };
};

export const updateAdminCustomerBlockStatus = async (
  customerId: string,
  isBlocked: boolean,
  reason?: string
) => {
  if (typeof isBlocked !== "boolean") {
    throw new HttpError(400, "is_blocked must be a boolean");
  }

  const customer = await getCustomerOrThrow(customerId);

  if (isBlocked) {
    const blockedReason = reason?.trim();
    if (!blockedReason) {
      throw new HttpError(400, "Reason is required when blocking customer");
    }
    customer.is_blocked = true;
    customer.blocked_reason = blockedReason;
  } else {
    customer.is_blocked = false;
    customer.blocked_reason = undefined;
  }

  await customer.save();

  return {
    message: isBlocked ? "Customer blocked successfully" : "Customer unblocked successfully",
  };
};

export const getAdminCustomerRideHistory = async (customerId: string) => {
  const customer = await getCustomerOrThrow(customerId);
  const rides = await RideModel.find({ customer_id: customer.id }).sort({ createdAt: -1 });

  return {
    customer: {
      id: customer.id,
      name: customer.name,
      email: customer.email,
