          },
        },
      },
      {
        $project: { _id: 0, totalRevenue: 1, onlineRevenue: 1, cashRevenue: 1 },
      },
    ]
  );

  return (
    totals ?? {
      totalRevenue: 0,
      onlineRevenue: 0,
      cashRevenue: 0,
