export const verifyRideOtpAndStartRide = async (
  driverIdInput: string | undefined,
  rideIdInput: string | undefined,
  otpInput: number
) => {
  const driver = await getDriverOrThrow(driverIdInput);
  const ride = await getRideByIdOrThrow(rideIdInput);

  ensureRideBelongsToDriver(ride, driver.id);
  if (ride.status !== "ARRIVED_AT_PICKUP") {
    throw new HttpError(400, "Ride must be in ARRIVED_AT_PICKUP state");
  }
  if (ride.otp_verified) {
    throw new HttpError(400, "OTP already verified for this ride");
  }

  if (ride.otp !== otpInput) {
    logger.warn(
      {
        ride_id: ride.id,
        driver_id: driver.id,
      },
      "Ride OTP verification failed"
    );
    throw new HttpError(400, "Invalid OTP");
  }

  ride.otp_verified = true;
  ride.status = "STARTED";
  await ride.save();

  logger.info(
    {
      ride_id: ride.id,
      driver_id: driver.id,
    },
    "Ride OTP verified"
  );
  const customerId = String(ride.customer_id);
  const statusForClient = toClientStatus(ride.status);
  console.log("STATUS EMIT:", statusForClient);
  console.log("Emitting to customer:", customerId);
  emitToCustomer(customerId, "ride_status_update", {
    ride_id: ride.id,
    status: statusForClient,
    ride: mapIncomingRide(ride),
  });
  emitToRide(ride.id, "ride_status_update", {
    ride_id: ride.id,
    status: statusForClient,
    ride: mapIncomingRide(ride),
  });
  await sendRideStatusPush(customerId, ride.id, "RIDE_STARTED", "Ride Started 🟢", "Enjoy your trip");

  return {
    message: "OTP verified, ride started",
    ride_id: ride.id,
    status: ride.status,
  };
};

export const getDriverRideHistory = async (driverIdInput: string | undefined) => {
  const driver = await getDriverOrThrow(driverIdInput);

  const rides = await RideModel.find({ driver_id: driver.id }).sort({ createdAt: -1 });

  const detailedRides = await Promise.all(
    rides.map(async (ride) => {
      const customer = await UserModel.findOne({ _id: ride.customer_id, role: "CUSTOMER" });

      return {
        ride_id: ride.id,
        status: ride.status,
        pickup: ride.pickup,
        drop: ride.drop,
        distance_km: ride.distance_km,
        duration_min: ride.duration_min ?? null,
        fare: ride.fare,
        customer: customer
          ? {
              id: customer.id,
              name: customer.name,
              email: customer.email,
              phone: customer.phone ?? null,
            }
          : null,
        createdAt: ride.createdAt,
        updatedAt: ride.updatedAt,
      };
    })
  );

  return {
    rides: detailedRides,
  };
};

const normalizeStatusAlias = (statusInput: string): RideStatus => {
  switch (statusInput) {
    case "SEARCHING":
      return "SEARCHING_DRIVER";
    case "ACCEPTED":
      return "DRIVER_ASSIGNED";
    case "DRIVER_ARRIVING":
      return "ARRIVED_AT_PICKUP";
    case "ARRIVED":
      return "ARRIVED_AT_PICKUP";
    case "STARTED":
      return "STARTED";
    case "COMPLETED":
      return "COMPLETED";
    case "CANCELLED":
      return "CANCELLED";
    default:
      throw new HttpError(400, "Unsupported status");
  }
};

export const updateRideStatusByDriver = async (
  driverIdInput: string | undefined,
  rideIdInput: string | undefined,
  statusInput: string
) => {
  const driver = await getDriverOrThrow(driverIdInput);
  const ride = await getRideByIdOrThrow(rideIdInput);
  ensureRideBelongsToDriver(ride, driver.id);

  const nextStatus = normalizeStatusAlias(statusInput);
  ride.status = nextStatus;
  if (nextStatus === "COMPLETED" && ride.payment_mode === "CASH") {
    ride.payment_status = "SUCCESS";
  }
  await ride.save();

  const customerId = String(ride.customer_id);
  const statusForClient = toClientStatus(ride.status);
  console.log("STATUS EMIT:", statusForClient);
  console.log("Emitting to customer:", customerId);
  emitToCustomer(customerId, "ride_status_update", {
    ride_id: ride.id,
    status: statusForClient,
    ride: mapIncomingRide(ride),
  });
  emitToRide(ride.id, "ride_status_update", {
    ride_id: ride.id,
    status: statusForClient,
    ride: mapIncomingRide(ride),
  });

  return {
    message: "Ride status updated",
    ride_id: ride.id,
    status: ride.status,
  };
};

import { Types } from "mongoose";
import { getIO } from "../../socket/socket";
import { calculateCommission } from "../common/commission.service";
import { RideDocument, RideModel } from "../customer/ride/ride.model";
import { HttpError } from "../../utils/http-error";
import { InvoiceModel } from "./invoice.model";

const toInvoiceResponse = (invoice: {
  ride_id: Types.ObjectId;
  distance_km: number;
  fare: number;
  commission: number;
  driver_earning: number;
  payment_mode: string;
  payment_status: string;
}) => ({
  ride_id: String(invoice.ride_id),
  distance_km: invoice.distance_km,
  fare: invoice.fare,
  commission: invoice.commission,
  driver_earning: invoice.driver_earning,
  payment_mode: invoice.payment_mode,
  payment_status: invoice.payment_status,
});

export const generateInvoice = async (rideInput: RideDocument) => {
  const ride = await RideModel.findById(rideInput._id);
  if (!ride) {
    throw new HttpError(404, "Ride not found");
  }
  if (ride.status !== "COMPLETED") {
    throw new HttpError(400, "Invoice can be generated only for completed rides");
  }
  if (!ride.driver_id || !ride.payment_mode || !ride.payment_status) {
    throw new HttpError(400, "Invalid ride data for invoice generation");
  }

  const existing = await InvoiceModel.findOne({ ride_id: ride._id });
  if (existing) {
    return toInvoiceResponse(existing);
  }

  const { commission, driverAmount } = calculateCommission(ride.fare);

  const paymentMode = ride.payment_mode;
  const paymentStatus = paymentMode === "CASH" ? "SUCCESS" : "PENDING";

  try {
    const invoice = await InvoiceModel.create({
      ride_id: ride._id,
      customer_id: ride.customer_id,
      driver_id: ride.driver_id,
      distance_km: ride.distance_km,
      fare: ride.fare,
      commission,
      driver_earning: driverAmount,
      payment_mode: paymentMode,
      payment_status: paymentStatus,
    });

    const io = getIO();
    io.to(`customer_${String(ride.customer_id)}`).emit("invoice_generated", toInvoiceResponse(invoice));
    io.to(`driver_${String(ride.driver_id)}`).emit("invoice_generated", toInvoiceResponse(invoice));

    return toInvoiceResponse(invoice);
  } catch (error: any) {
    // In case of race-condition duplicate invoice creation, fall back to existing.
    if (error?.code === 11000) {
      const existingAfterRace = await InvoiceModel.findOne({ ride_id: ride._id });
      if (existingAfterRace) {
        return toInvoiceResponse(existingAfterRace);
      }
    }
    throw error;
  }
};

export const updateInvoicePaymentStatusToSuccess = async (rideId: Types.ObjectId) => {
  const updated = await InvoiceModel.findOneAndUpdate(
    { ride_id: rideId },
    { payment_status: "SUCCESS" },
    { new: true }
  );

  if (!updated) {
    return null;
  }

  const io = getIO();
  io.to(`customer_${String(updated.customer_id)}`).emit("invoice_updated", toInvoiceResponse(updated));
  io.to(`driver_${String(updated.driver_id)}`).emit("invoice_updated", toInvoiceResponse(updated));

  return toInvoiceResponse(updated);
};

import { HydratedDocument, Schema, Types, model } from "mongoose";

export const INVOICE_PAYMENT_MODES = ["ONLINE", "CASH"] as const;
export type InvoicePaymentMode = (typeof INVOICE_PAYMENT_MODES)[number];

export const INVOICE_PAYMENT_STATUSES = ["PENDING", "SUCCESS"] as const;
export type InvoicePaymentStatus = (typeof INVOICE_PAYMENT_STATUSES)[number];

export type InvoiceEntity = {
  ride_id: Types.ObjectId;
  customer_id: Types.ObjectId;
  driver_id: Types.ObjectId;

  distance_km: number;

  fare: number;
  commission: number;
  driver_earning: number;

  payment_mode: InvoicePaymentMode;
  payment_status: InvoicePaymentStatus;
};

export type InvoiceDocument = HydratedDocument<InvoiceEntity>;

const invoiceSchema = new Schema<InvoiceEntity>(
  {
    ride_id: { type: Schema.Types.ObjectId, ref: "Ride", required: true, unique: true, index: true },
    customer_id: { type: Schema.Types.ObjectId, ref: "User", required: true, index: true },
    driver_id: { type: Schema.Types.ObjectId, ref: "User", required: true, index: true },

    distance_km: { type: Number, required: true, min: 0 },

    fare: { type: Number, required: true, min: 0 },
    commission: { type: Number, required: true, min: 0 },
    driver_earning: { type: Number, required: true, min: 0 },

    payment_mode: { type: String, enum: INVOICE_PAYMENT_MODES, required: true, index: true },
    payment_status: { type: String, enum: INVOICE_PAYMENT_STATUSES, required: true, index: true },
  },
  {
    collection: "invoices",
    timestamps: true,
  }
);

invoiceSchema.index({ customer_id: 1, createdAt: -1 });
invoiceSchema.index({ driver_id: 1, createdAt: -1 });

export const InvoiceModel = model<InvoiceEntity>("Invoice", invoiceSchema);

