import { Types } from "mongoose";
import { UserModel } from "../users/users.model";
import { HttpError } from "../../utils/http-error";
import type { Readable } from "stream";
import { deleteFile, getObjectForDownload, uploadFile, type UploadableFile } from "../../utils/s3";
import { DriverDocumentModel, type DriverDocumentType } from "./driver-document.model";

function assertDriver(user: { role: string } | null): asserts user is NonNullable<typeof user> {
  if (!user) {
    throw new HttpError(404, "User not found");
  }
  if (user.role !== "DRIVER") {
    throw new HttpError(403, "Only drivers can perform this action");
  }
}

export type DriverDocumentView = {
  id: string;
  user_id: string;
  document_type: DriverDocumentType;
  file_url: string;
  file_key: string;
  status: string;
  rejection_reason: string | null;
};

function mapDocument(doc: {
  _id: Types.ObjectId;
  user_id: Types.ObjectId;
  document_type: DriverDocumentType;
  file_url: string;
  file_key: string;
  status: string;
  rejection_reason?: string | null;
}): DriverDocumentView {
  return {
    id: String(doc._id),
    user_id: String(doc.user_id),
    document_type: doc.document_type,
    file_url: doc.file_url,
    file_key: doc.file_key,
    status: doc.status,
    rejection_reason: doc.rejection_reason ?? null,
  };
}

export async function uploadDocument(
  userId: string,
  documentType: DriverDocumentType,
  file: UploadableFile
): Promise<DriverDocumentView> {
  const user = await UserModel.findById(userId);
  assertDriver(user);

  const folder = `driver-documents/${userId}`;
  const uploaded = await uploadFile(file, folder);

  const created = await DriverDocumentModel.create({
    user_id: new Types.ObjectId(userId),
    document_type: documentType,
    file_url: uploaded.file_url,
    file_key: uploaded.file_key,
    status: "PENDING",
  });

  return mapDocument(created.toObject());
}

export async function getDriverDocuments(userId: string): Promise<DriverDocumentView[]> {
  const user = await UserModel.findById(userId);
  assertDriver(user);

  const docs = await DriverDocumentModel.find({ user_id: new Types.ObjectId(userId) })
    .sort({ createdAt: -1 })
    .lean();

  return docs.map((doc) =>
    mapDocument({
      _id: doc._id as Types.ObjectId,
      user_id: doc.user_id as Types.ObjectId,
      document_type: doc.document_type,
      file_url: doc.file_url,
      file_key: doc.file_key,
      status: doc.status,
      rejection_reason: doc.rejection_reason,
    })
  );
}

export async function getDocumentById(docId: string, userId: string): Promise<DriverDocumentView> {
  const user = await UserModel.findById(userId);
  assertDriver(user);

  const doc = await DriverDocumentModel.findById(docId).lean();
  if (!doc) {
    throw new HttpError(404, "Document not found");
  }
  if (String(doc.user_id) !== userId) {
    throw new HttpError(403, "You cannot access this document");
  }

  return mapDocument({
    _id: doc._id as Types.ObjectId,
    user_id: doc.user_id as Types.ObjectId,
    document_type: doc.document_type,
    file_url: doc.file_url,
    file_key: doc.file_key,
    status: doc.status,
    rejection_reason: doc.rejection_reason,
  });
}

export type DocumentDownloadStream = {
  stream: Readable;
  contentType: string;
  contentLength?: number;
  filename: string;
};

function attachmentFilenameFromFileKey(fileKey: string): string {
  const base = fileKey.split("/").pop() || "document";
  const safe = base.replace(/[^\w.\-]+/g, "_");
  return safe.length > 0 ? safe : "document";
}

/** Auth + DB check, then S3 GetObject stream (private bucket safe). */
export async function streamDriverDocumentForDownload(
  docId: string,
  userId: string
): Promise<DocumentDownloadStream> {
  const doc = await getDocumentById(docId, userId);
  const key = doc.file_key?.trim();
  if (!key) {
    throw new HttpError(404, "Document file not found");
  }
  const { body, contentType, contentLength } = await getObjectForDownload(key);
  return {
    stream: body,
    contentType,
    contentLength,
    filename: attachmentFilenameFromFileKey(key),
  };
}

export async function streamAdminDocumentForDownload(docId: string): Promise<DocumentDownloadStream> {
  const doc = await DriverDocumentModel.findById(docId).lean();
  if (!doc) {
    throw new HttpError(404, "Document not found");
  }
  const key = doc.file_key?.trim();
  if (!key) {
    throw new HttpError(404, "Document file not found");
  }
  const { body, contentType, contentLength } = await getObjectForDownload(key);
  return {
    stream: body,
    contentType,
    contentLength,
    filename: attachmentFilenameFromFileKey(key),
  };
}

export async function reuploadDocument(
  docId: string,
  userId: string,
  file: UploadableFile
): Promise<DriverDocumentView> {
  const user = await UserModel.findById(userId);
  assertDriver(user);

  const doc = await DriverDocumentModel.findById(docId);
  if (!doc) {
    throw new HttpError(404, "Document not found");
  }
  if (String(doc.user_id) !== userId) {
    throw new HttpError(403, "You cannot modify this document");
  }
  if (doc.status !== "REJECTED") {
    throw new HttpError(400, "Reupload is only allowed for rejected documents");
  }

  const folder = `driver-documents/${userId}`;
  const uploaded = await uploadFile(file, folder);

  if (doc.file_key) {
    await deleteFile(doc.file_key).catch(() => undefined);
  }

  doc.file_url = uploaded.file_url;
  doc.file_key = uploaded.file_key;
  doc.status = "PENDING";
  doc.rejection_reason = undefined;
  await doc.save();

  return mapDocument(doc.toObject());
}

export async function adminGetDriversForVerification() {
  const drivers = await UserModel.find({
    role: "DRIVER",
    is_driver_verified: false,
  })
    .select("_id name email phone driver_verification_status created_at")
    .sort({ created_at: -1 })
    .lean();

  const ids = drivers.map((d) => d._id as Types.ObjectId);
  if (ids.length === 0) {
    return [];
  }

  const counts = await DriverDocumentModel.aggregate<{ _id: Types.ObjectId; count: number }>([
    { $match: { user_id: { $in: ids } } },
    { $group: { _id: "$user_id", count: { $sum: 1 } } },
  ]);

  const countMap = new Map<string, number>();
  for (const row of counts) {
    countMap.set(String(row._id), row.count);
  }

  return drivers.map((driver) => ({
    id: String(driver._id),
    name: driver.name,
    email: driver.email,
    phone: driver.phone ?? null,
    driver_verification_status: driver.driver_verification_status ?? "PENDING",
    documents_uploaded_count: countMap.get(String(driver._id)) ?? 0,
  }));
}

export async function adminGetDriverDocuments(driverId: string): Promise<DriverDocumentView[]> {
  const driver = await UserModel.findById(driverId).lean();
  if (!driver) {
    throw new HttpError(404, "Driver not found");
  }
  if (driver.role !== "DRIVER") {
    throw new HttpError(400, "User is not a driver");
  }

  const docs = await DriverDocumentModel.find({ user_id: new Types.ObjectId(driverId) })
    .sort({ createdAt: -1 })
    .lean();

  return docs.map((doc) =>
    mapDocument({
      _id: doc._id as Types.ObjectId,
      user_id: doc.user_id as Types.ObjectId,
      document_type: doc.document_type,
      file_url: doc.file_url,
      file_key: doc.file_key,
      status: doc.status,
      rejection_reason: doc.rejection_reason,
    })
  );
}

export async function adminUpdateDocumentStatus(
  docId: string,
  status: "APPROVED" | "REJECTED",
  reason?: string
): Promise<DriverDocumentView> {
  const doc = await DriverDocumentModel.findById(docId);
  if (!doc) {
    throw new HttpError(404, "Document not found");
  }

  doc.status = status;
  if (status === "REJECTED") {
    if (!reason?.trim()) {
      throw new HttpError(400, "Rejection reason is required");
    }
    doc.rejection_reason = reason.trim();
  } else {
    doc.rejection_reason = undefined;
  }

  await doc.save();
  return mapDocument(doc.toObject());
}

export async function adminFinalApproveDriver(driverId: string) {
  const driver = await UserModel.findById(driverId);
  if (!driver) {
    throw new HttpError(404, "Driver not found");
  }
  if (driver.role !== "DRIVER") {
    throw new HttpError(400, "User is not a driver");
  }

  const docs = await DriverDocumentModel.find({ user_id: new Types.ObjectId(driverId) }).lean();

  const markPending = async (): Promise<void> => {
    driver.is_driver_verified = false;
    driver.driver_verification_status = "PENDING";
    await driver.save();
  };

  if (docs.length === 0) {
    await markPending();
    throw new HttpError(
      400,
      "Final approval requires at least one uploaded document; driver verification left as PENDING"
    );
  }

  const notApproved = docs.filter((d) => d.status !== "APPROVED");
  if (notApproved.length > 0) {
    await markPending();
    const summary = notApproved.map((d) => `${d.document_type}: ${d.status}`).join("; ");
    throw new HttpError(
      400,
      `All uploaded documents must be APPROVED before final approval (found ${docs.length} upload(s)). Not approved: ${summary}. Driver verification set to PENDING.`
    );
  }

  driver.is_driver_verified = true;
  driver.driver_verification_status = "APPROVED";
  await driver.save();

  return {
    driver_id: String(driver._id),
    is_driver_verified: driver.is_driver_verified,
    driver_verification_status: driver.driver_verification_status,
  };
}

export async function validateDriverVerified(userId: string): Promise<void> {
  const user = await UserModel.findById(userId).lean();
  if (!user) {
    throw new HttpError(404, "User not found");
  }
  if (user.role !== "DRIVER") {
    throw new HttpError(403, "Not a driver account");
  }
  if (!user.is_driver_verified || user.driver_verification_status !== "APPROVED") {
    throw new HttpError(403, "Driver is not verified");
  }
}

import { DeleteObjectCommand, GetObjectCommand, PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";
import { randomBytes } from "crypto";
import type { Readable } from "stream";
import { env } from "../config/env";
import { HttpError } from "./http-error";

let s3Client: S3Client | null = null;

function requireAwsConfig(): { client: S3Client; bucket: string; region: string } {
  const accessKeyId = env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = env.AWS_SECRET_ACCESS_KEY;
  const region = env.AWS_REGION;
  const documentsBucket = env.AWS_S3_BUCKET_DOCUMENTS?.trim();
  const bucket = documentsBucket || env.AWS_S3_BUCKET;

  if (!accessKeyId || !secretAccessKey || !region || !bucket) {
    throw new HttpError(503, "File storage is not configured");
  }

  if (!s3Client) {
    s3Client = new S3Client({
      region,
      credentials: {
        accessKeyId,
        secretAccessKey,
      },
    });
  }

  return { client: s3Client, bucket, region };
}

function buildPublicObjectUrl(bucket: string, region: string, key: string): string {
  const safeKey = key.split("/").map((segment) => encodeURIComponent(segment)).join("/");
  return `https://${bucket}.s3.${region}.amazonaws.com/${safeKey}`;
}

export type UploadableFile = {
  buffer: Buffer;
  mimetype: string;
  originalname: string;
};

export async function uploadFile(
  file: UploadableFile,
  folder: string
): Promise<{ file_url: string; file_key: string }> {
  const { client, bucket, region } = requireAwsConfig();
  const safeFolder = folder.replace(/^\/+|\/+$/g, "");
  const ext = file.originalname.includes(".") ? file.originalname.slice(file.originalname.lastIndexOf(".")) : "";
  const key = `${safeFolder}/${Date.now()}-${randomBytes(8).toString("hex")}${ext}`;

  // Omit ACL — "Bucket owner enforced" buckets reject ACL: public-read (AccessControlListNotSupported).
  await client.send(
    new PutObjectCommand({
      Bucket: bucket,
      Key: key,
      Body: file.buffer,
      ContentType: file.mimetype || "application/octet-stream",
    })
  );

  return {
    file_key: key,
    file_url: buildPublicObjectUrl(bucket, region, key),
  };
}

/** Presigned GET URL (optional: mobile / CDN). Downloads should prefer {@link getObjectForDownload}. */
export async function getSignedReadUrl(fileKey: string, expiresInSeconds = 900): Promise<string> {
  const { client, bucket } = requireAwsConfig();
  const command = new GetObjectCommand({ Bucket: bucket, Key: fileKey });
  return getSignedUrl(client, command, { expiresIn: expiresInSeconds });
}

export type S3ObjectDownload = {
  body: Readable;
  contentType: string;
  contentLength?: number;
};

/**
 * Stream object bytes from the configured documents bucket (server-side; works with private objects).
 * Requires IAM s3:GetObject on the bucket.
 */
export async function getObjectForDownload(fileKey: string): Promise<S3ObjectDownload> {
  const key = fileKey.trim();
  if (!key) {
    throw new HttpError(400, "Invalid file key");
  }

  const { client, bucket } = requireAwsConfig();
  try {
    const out = await client.send(
      new GetObjectCommand({
        Bucket: bucket,
        Key: key,
      })
    );
    if (!out.Body) {
      throw new HttpError(404, "File not found");
    }
    return {
      body: out.Body as Readable,
      contentType: (out.ContentType && out.ContentType.trim()) || "application/octet-stream",
      contentLength: out.ContentLength,
    };
  } catch (e: unknown) {
    const name = e && typeof e === "object" && "name" in e ? String((e as { name: string }).name) : "";
    if (name === "NoSuchKey") {
      throw new HttpError(404, "File not found");
    }
    throw e;
  }
}

export async function deleteFile(fileKey: string): Promise<void> {
  if (!fileKey) {
    return;
  }

  const { client, bucket } = requireAwsConfig();
  await client.send(
    new DeleteObjectCommand({
      Bucket: bucket,
      Key: fileKey,
    })
  );
}

import { Schema, Types, model, HydratedDocument } from "mongoose";

export const DRIVER_DOCUMENT_TYPES = ["IDENTITY", "VEHICLE", "BANK", "PERSONAL"] as const;
export type DriverDocumentType = (typeof DRIVER_DOCUMENT_TYPES)[number];

export const DRIVER_DOCUMENT_STATUSES = ["PENDING", "APPROVED", "REJECTED"] as const;
export type DriverDocumentStatus = (typeof DRIVER_DOCUMENT_STATUSES)[number];

export type DriverDocumentEntity = {
  user_id: Types.ObjectId;
  document_type: DriverDocumentType;
  file_url: string;
  file_key: string;
  status: DriverDocumentStatus;
  rejection_reason?: string;
};

export type DriverDocumentDocument = HydratedDocument<DriverDocumentEntity>;

const driverDocumentSchema = new Schema<DriverDocumentEntity>(
  {
    user_id: {
      type: Schema.Types.ObjectId,
      ref: "User",
      required: true,
      index: true,
    },
    document_type: {
      type: String,
      enum: DRIVER_DOCUMENT_TYPES,
      required: true,
    },
    file_url: { type: String, required: true, trim: true },
    file_key: { type: String, required: true, trim: true },
    status: {
      type: String,
      enum: DRIVER_DOCUMENT_STATUSES,
      default: "PENDING",
    },
    rejection_reason: { type: String, default: undefined, trim: true },
  },
  {
    collection: "driver_documents",
    timestamps: true,
  }
);

/** Non-unique: multiple uploads per type are allowed; reupload replaces a specific doc by id. */
driverDocumentSchema.index({ user_id: 1, document_type: 1 });

export const DriverDocumentModel = model<DriverDocumentEntity>("DriverDocument", driverDocumentSchema);

import type { Request } from "express";
import multer from "multer";

/** Allowed multipart field names for the actual file (Postman-friendly). */
const DRIVER_DOC_FIELD_NAMES = ["file", "aadhar", "document"] as const;

export const driverDocumentFileUpload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: 15 * 1024 * 1024 },
}).fields(
  DRIVER_DOC_FIELD_NAMES.map((name) => ({
    name,
    maxCount: 1,
  }))
);

export function getDriverUploadedFile(req: Request): Express.Multer.File | undefined {
  const files = req.files as Record<string, Express.Multer.File[]> | undefined;
  if (!files) {
    return undefined;
  }
  for (const name of DRIVER_DOC_FIELD_NAMES) {
    const file = files[name]?.[0];
    if (file) {
      return file;
    }
  }
  return undefined;
}

import { z } from "zod";
import { Types } from "mongoose";
const objectIdParam = z
  .string()
  .min(1)
  .refine((value) => Types.ObjectId.isValid(value), { message: "Invalid id" });

/** Multipart body is file only; document_type is required on the query string. */
export const driverUploadDocumentSchema = z.object({
  body: z.object({}),
  params: z.object({}),
  query: z.object({
    document_type: z.enum(["IDENTITY", "VEHICLE", "BANK", "PERSONAL"], {
      errorMap: () => ({ message: "Invalid or missing document_type query param" }),
    }),
  }),
});

export const driverDocumentIdSchema = z.object({
  body: z.object({}),
  params: z.object({
    id: objectIdParam,
  }),
  query: z.object({}),
});

export const adminDriverIdSchema = z.object({
  body: z.object({}),
  params: z.object({
    driverId: objectIdParam,
  }),
  query: z.object({}),
});

export const adminDocumentIdSchema = z.object({
  body: z.object({}),
  params: z.object({
    id: objectIdParam,
  }),
  query: z.object({}),
});

export const adminDocumentStatusSchema = z.object({
  body: z
    .object({
      status: z.enum(["APPROVED", "REJECTED"], {
        errorMap: () => ({ message: "status must be APPROVED or REJECTED" }),
      }),
      reason: z.string().trim().optional(),
    })
    .superRefine((value, ctx) => {
      if (value.status === "REJECTED" && (!value.reason || value.reason.length === 0)) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          message: "reason is required when status is REJECTED",
        });
      }
    }),
  params: z.object({
    id: objectIdParam,
  }),
  query: z.object({}),
});

export const adminFinalApproveSchema = z.object({
  body: z.object({}),
  params: z.object({
    driverId: objectIdParam,
  }),
  query: z.object({}),
});

import { Router } from "express";
import { requireAuth } from "../../middlewares/auth.middleware";
import { requireRole } from "../../middlewares/role.middleware";
import { validate } from "../../middlewares/validate.middleware";
import {
  getDriverProfileExtendedController,
  upsertDriverProfileController,
} from "./driver-profile.controller";
import { upsertDriverProfileSchema } from "./driver-profile.validation";

const driverProfileRouter = Router();

driverProfileRouter.post(
  "/profile",
  requireAuth,
  requireRole(["DRIVER"]),
  validate(upsertDriverProfileSchema),
  upsertDriverProfileController
);

driverProfileRouter.get(
  "/profile",
  requireAuth,
  requireRole(["DRIVER"]),
  getDriverProfileExtendedController
);

export default driverProfileRouter;

import { NextFunction, Request, Response } from "express";
import { successResponse } from "../../utils/api-response";
import { HttpError } from "../../utils/http-error";
import {
  completeProfile,
  createOrUpdateProfile,
  getProfile,
} from "./driver-profile.service";
import type { UpsertDriverProfileInput } from "./driver-profile.validation";

function requireUserId(req: Request): string {
  const id = req.authUser?.userId;
  if (!id) {
    throw new HttpError(401, "Unauthorized");
  }
  return id;
}

export const upsertDriverProfileController = async (
  req: Request,
  res: Response,
  next: NextFunction
) => {
  try {
    const userId = requireUserId(req);
    const body = req.body as UpsertDriverProfileInput;
    const profile = await createOrUpdateProfile(userId, body);
    return res.status(200).json(successResponse("Driver profile saved", profile));
  } catch (error) {
    return next(error as Error);
  }
};

export const getDriverProfileExtendedController = async (
  req: Request,
  res: Response,
  next: NextFunction
) => {
  try {
    const userId = requireUserId(req);
    const profile = await getProfile(userId);
    return res.status(200).json(successResponse("Driver profile", profile));
  } catch (error) {
    return next(error as Error);
  }
};

export const completeDriverProfileController = async (
  req: Request,
  res: Response,
  next: NextFunction
) => {
  try {
    const userId = requireUserId(req);
    const profile = await completeProfile(userId);
    return res.status(200).json(successResponse("Driver profile marked complete", profile));
  } catch (error) {
    return next(error as Error);
  }
};

import { isValidObjectId } from "mongoose";
import { z } from "zod";

const PHONE_REGEX = /^\+?[0-9]{10,15}$/;
const IFSC_REGEX = /^[A-Z]{4}0[A-Z0-9]{6}$/i;
const AADHAAR_REGEX = /^\d{12}$/;
const PAN_REGEX = /^[A-Z]{5}[0-9]{4}[A-Z]$/i;

const optionalNonEmptyString = z
  .string()
  .trim()
  .optional()
  .transform((v) => (v === "" ? undefined : v));

const optionalPhone = optionalNonEmptyString.refine(
  (v) => v === undefined || PHONE_REGEX.test(v.replace(/\s/g, "")),
  { message: "phone must be 10–15 digits, optional leading +" }
);

const optionalIfsc = optionalNonEmptyString.refine(
  (v) => v === undefined || IFSC_REGEX.test(v),
  { message: "Invalid IFSC format (e.g. SBIN0001234)" }
);

const optionalAadhaar = optionalNonEmptyString.refine(
  (v) => v === undefined || AADHAAR_REGEX.test(v.replace(/\s/g, "")),
  { message: "aadhaar_number must be exactly 12 digits" }
);

const optionalPan = optionalNonEmptyString.refine(
  (v) => v === undefined || PAN_REGEX.test(v),
  { message: "Invalid PAN format (e.g. ABCDE1234F)" }
);

const optionalObjectIdString = optionalNonEmptyString.refine(
  (v) => v === undefined || isValidObjectId(v),
  { message: "vehicle_type_id must be a valid ObjectId" }
);

const optionalDate = z.preprocess((val) => {
  if (val === undefined || val === null || val === "") {
    return undefined;
  }
  if (val instanceof Date) {
    return val;
  }
  if (typeof val === "string" || typeof val === "number") {
    const d = new Date(val);
    return Number.isNaN(d.getTime()) ? val : d;
  }
  return val;
}, z.date().optional());

export const upsertDriverProfileBodySchema = z.object({
  dob: optionalDate,
  phone: optionalPhone,
  address: optionalNonEmptyString,
  emergency_contact: optionalNonEmptyString,
  license_number: optionalNonEmptyString,
  vehicle_reg_number: optionalNonEmptyString,
  vehicle_type_id: optionalObjectIdString,
  vehicle_model: optionalNonEmptyString,
  vehicle_color: optionalNonEmptyString,
  pan_number: optionalPan,
  aadhaar_number: optionalAadhaar,
  voter_id: optionalNonEmptyString,
  account_holder_name: optionalNonEmptyString,
  bank_name: optionalNonEmptyString,
  branch_name: optionalNonEmptyString,
  account_number: optionalNonEmptyString,
  ifsc_code: optionalIfsc,
  account_type: optionalNonEmptyString,
  upi_id: optionalNonEmptyString,
});

export const upsertDriverProfileSchema = z.object({
  body: upsertDriverProfileBodySchema,
  params: z.object({}),
  query: z.object({}),
});

export const completeDriverProfileSchema = z.object({
  body: z.object({}),
  params: z.object({}),
  query: z.object({}),
});

export type UpsertDriverProfileInput = z.infer<typeof upsertDriverProfileBodySchema>;

import { NextFunction, Request, Response } from "express";
import multer from "multer";
import { logger } from "../config/logger";
import { errorResponse } from "../utils/api-response";

type ErrorWithStatus = Error & { statusCode?: number };

function multerClientMessage(err: multer.MulterError): string {
  if (err.code === "LIMIT_UNEXPECTED_FILE") {
    return `Unexpected form field "${err.field ?? ""}". Allowed file field names are: file, aadhar, document.`;
  }
  if (err.code === "LIMIT_FILE_SIZE") {
    return "File too large. Maximum size is 15 MB.";
  }
  return err.message || "Upload failed";
}

export const notFoundHandler = (req: Request, res: Response) => {
  return res.status(404).json(
    errorResponse("Route not found", {
      method: req.method,
      path: req.originalUrl,
      hint: "Check method and endpoint path. Example: POST /api/v1/auth/login",
    })
  );
};

export const globalErrorHandler = (
  err: ErrorWithStatus,
  req: Request,
  res: Response,
  _next: NextFunction
) => {
  if (err instanceof multer.MulterError) {
    logger.warn({ err }, "Multer upload rejected");
    return res.status(400).json(
      errorResponse(multerClientMessage(err), {
        method: req.method,
        path: req.originalUrl,
        code: err.code,
        field: err.field,
      })
    );
  }

  const statusCode = err.statusCode || 500;
  logger.error({ err }, "Request failed");

  if (statusCode >= 500) {
    return res.status(statusCode).json(
      errorResponse("Internal server error", {
        method: req.method,
        path: req.originalUrl,
      })
    );
  }

  return res.status(statusCode).json(
    errorResponse(err.message, {
      method: req.method,
      path: req.originalUrl,
    })
  );
};

import mongoose from "mongoose";
import { MONGO_URI } from "../config/env";
import { logger } from "../config/logger";

const MAX_RETRIES = 5;
const RETRY_DELAY_MS = 5000;

const wait = async (ms: number): Promise<void> =>
  new Promise((resolve) => {
    setTimeout(resolve, ms);
  });

export const connectDatabase = async (): Promise<void> => {
  let retries = 0;
  console.log("Mongo URI:", MONGO_URI);

  while (retries < MAX_RETRIES) {
    try {
      await mongoose.connect(MONGO_URI);
      logger.info("MongoDB connected");
      return;
    } catch (error) {
      retries += 1;
      logger.error({ error, retries }, "MongoDB connection failed");

      if (retries >= MAX_RETRIES) {
        throw new Error("Unable to connect to MongoDB after retries");
      }

      await wait(RETRY_DELAY_MS);
    }
  }
};

export const disconnectDatabase = async (): Promise<void> => {
  await mongoose.connection.close();
  logger.info("MongoDB disconnected");
};

import admin from "../../config/firebase";
import { logger } from "../../config/logger";

type PushData = {
  ride_id?: string;
  type?: string;
  status?: string;
};

const toStringMap = (data?: PushData): Record<string, string> => {
  const entries = Object.entries(data ?? {}).filter(
    ([, value]) => value !== undefined && value !== null && String(value).trim() !== ""
  );
  return Object.fromEntries(entries.map(([key, value]) => [key, String(value)]));
};

export const sendPushNotification = async (
  token: string | undefined,
  title: string,
  body: string,
  data?: PushData
): Promise<void> => {
  if (!token || token.trim() === "") {
    return;
  }

  try {
    await admin.messaging().send({
      token,
      notification: { title, body },
      data: toStringMap(data),
    });
  } catch (error) {
    logger.error({ error }, "Failed to send push notification");
  }
};

